import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { loginUser } from "../services/api";
import { Box, TextField, Button, Typography, Paper, Grid, InputAdornment } from "@mui/material";
import { makeStyles } from "@mui/styles";
import { AccountCircle, LockIcon } from "@mui/icons-material";

const useStyles = makeStyles((theme) => ({
    container: {
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        height: '100vh',
        background: 'linear-gradient(135deg, #6a1b9a, #9c27b0)', // Purple gradient background
        overflow: 'hidden',
    },
    formContainer: {
        width: '100%',
        maxWidth: 450,
        padding: theme.spacing(5),
        borderRadius: '12px',
        boxShadow: '0 4px 30px rgba(0, 0, 0, 0.2)',
        background: '#fff',
        textAlign: 'center',
        animation: 'slideIn 1s ease-out',
    },
    title: {
        color: '#9c27b0', // Lighter purple title color
        marginBottom: theme.spacing(3),
        fontWeight: '600',
    },
    input: {
        marginBottom: theme.spacing(2),
        '& label': {
            color: '#9c27b0', // Light purple label color
        },
        '& .MuiOutlinedInput-root': {
            '& fieldset': {
                borderColor: '#9c27b0', // Purple border color
            },
            '&:hover fieldset': {
                borderColor: '#6a1b9a', // Darker purple on hover
            },
            '&.Mui-focused fieldset': {
                borderColor: '#6a1b9a', // Focused border color
            },
        },
    },
    button: {
        background: '#9c27b0',
        color: '#fff',
        '&:hover': {
            background: '#6a1b9a', // Dark purple on hover
        },
        padding: theme.spacing(1.5),
        fontWeight: 'bold',
    },
    footerText: {
        marginTop: theme.spacing(3),
        color: '#9c27b0',
        fontSize: '14px',
    },
    '@keyframes slideIn': {
        '0%': { opacity: 0, transform: 'translateY(-100px)' },
        '100%': { opacity: 1, transform: 'translateY(0)' },
    },
    icon: {
        color: '#9c27b0',
    },
}));

const Login = () => {
    const classes = useStyles();
    const [username, setUsername] = useState("");
    const [password, setPassword] = useState("");
    const navigate = useNavigate();

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const { data } = await loginUser({ username, password });
            console.log(data); // Log the response to see what the backend is returning
            if (data.token) {
                localStorage.setItem("token", data.token);
                if (data.user.role === "superadmin") navigate("/superadmin");
                else if (data.user.role === "admin") navigate("/admin");
                else navigate("/user");
            } else {
                alert("Invalid Credentials");
            }
        } catch (error) {
            console.error("Login failed:", error);
            alert("Invalid Credentials");
        }
    };

    return (
        <Box className={classes.container}>
            <Paper className={classes.formContainer}>
                <Typography variant="h5" className={classes.title}>
                    Welcome Back
                </Typography>
                <form onSubmit={handleSubmit}>
                    <TextField
                        label="Username"
                        variant="outlined"
                        value={username}
                        onChange={(e) => setUsername(e.target.value)}
                        fullWidth
                        className={classes.input}
                        InputProps={{
                            startAdornment: (
                                <InputAdornment position="start">
                                    <AccountCircle className={classes.icon} />
                                </InputAdornment>
                            ),
                        }}
                    />
                    <TextField
                        label="Password"
                        variant="outlined"
                        type="password"
                        value={password}
                        onChange={(e) => setPassword(e.target.value)}
                        fullWidth
                        className={classes.input}
                        InputProps={{
                            startAdornment: (
                                <InputAdornment position="start">
                                    <LockIcon className={classes.icon} />
                                </InputAdornment>
                            ),
                        }}
                    />
                    <Button
                        type="submit"
                        variant="contained"
                        fullWidth
                        className={classes.button}
                    >
                        Login
                    </Button>
                </form>
                <Typography className={classes.footerText}>
                    Don't have an account? <span style={{ fontWeight: 'bold' }}>Sign Up</span>
                </Typography>
            </Paper>
        </Box>
    );
};

export default Login;
